fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        // Empty input -> return empty vector
        return Vec::new();
    }
    
    // Capacity for the resulting vector: 2n - 1
    let mut result = Vec::with_capacity(2 * n - 1);
    
    for i in 0..n - 1 {
        result.push(numbers[i]);
        result.push(delim);
    }

    // Push the last element (no trailing delimiter after it)
    result.push(numbers[n - 1]);
    
    result
}